function AuthPage({ mode }: { mode: 'sign-in' | 'sign-up' }) {
  const shared = {
    theme: shadcn,
    cssLayerName: 'clerk',
    options: {
      logoPlacement: 'inside' as const,
      logoLinkUrl: basePath || '/',
      logoImageUrl: `${window.location.origin}${basePath}/logo.svg`,
    },
    variables: {
      colorPrimary: 'hsl(65 72% 48%)',
      colorForeground: 'hsl(216 29% 17%)',
      colorMutedForeground: 'hsl(215 12% 46%)',
      colorBackground: 'hsl(42 32% 99%)',
      colorInput: 'hsl(42 27% 96%)',
      colorInputForeground: 'hsl(216 29% 17%)',
      colorNeutral: 'hsl(38 18% 81%)',
      colorDanger: 'hsl(6 69% 52%)',
      fontFamily: 'Manrope, sans-serif',
      borderRadius: '0.75rem',
    },
    elements: {
      rootBox: 'w-full flex justify-center',
      cardBox: 'bg-card rounded-2xl w-[440px] max-w-full overflow-hidden',
      card: '!shadow-none !border-0 !bg-transparent !rounded-none',
      footer: '!shadow-none !border-0 !bg-transparent !rounded-none',
      headerTitle: 'text-foreground',
      headerSubtitle: 'text-muted-foreground',
      socialButtonsBlockButtonText: 'text-foreground',
      formFieldLabel: 'text-foreground',
      footerActionLink: 'text-primary',
      footerActionText: 'text-muted-foreground',
      dividerText: 'text-muted-foreground',
      identityPreviewEditButton: 'text-primary',
      formFieldSuccessText: 'text-emerald-700',
      alertText: 'text-foreground',
      logoBox: 'h-10',
      logoImage: 'h-10 w-auto',
      socialButtonsBlockButton: 'border-border bg-background',
      formButtonPrimary: 'bg-primary text-primary-foreground hover:brightness-95',
      formFieldInput: 'border-input bg-background text-foreground',
      footerAction: 'bg-transparent',
      dividerLine: 'bg-border',
      alert: 'border-border bg-secondary',
      otpCodeFieldInput: 'border-input bg-background text-foreground',
      formFieldRow: 'text-foreground',
      main: 'bg-transparent',
    },
  };
  return <div className="flex min-h-[100dvh] items-center justify-center bg-sidebar px-4 py-8"><div className="hidden max-w-sm flex-1 text-sidebar-foreground lg:block lg:pr-16"><Brand /><p className="mt-16 font-mono text-[10px] uppercase tracking-[.16em] text-sidebar-primary">Secure workspace access</p><h1 className="mt-4 text-5xl font-extrabold leading-[.98] tracking-[-.07em]">The floor is<br />waiting.</h1><p className="mt-6 text-sm leading-6 text-sidebar-foreground/60">Your gym’s next good decision is usually one clear view away.</p></div><div className="w-full max-w-[440px] rounded-2xl bg-card p-2 shadow-2xl"><div className="rounded-xl bg-card p-2">{mode === 'sign-in' ? <SignIn routing="path" path={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`} fallbackRedirectUrl={`${basePath}/dashboard`} forceRedirectUrl={`${basePath}/dashboard`} appearance={shared} /> : <SignUp routing="path" path={`${basePath}/sign-up`} signInUrl={`${basePath}/sign-in`} fallbackRedirectUrl={`${basePath}/dashboard`} forceRedirectUrl={`${basePath}/dashboard`} appearance={shared} />}</div></div></div>;
}

function WorkspaceRouter() {
  const [location] = useLocation();
  const publicPage = location === '/';
  return <ErrorBoundary resetKey={location}>{publicPage ? <Switch><Route path="/" component={LandingPage} /><Route component={NotFound} /></Switch> : <><Show when="signed-in"><AppShell><Switch><Route path="/dashboard" component={DashboardPage} /><Route path="/members" component={MembersPage} /><Route path="/members/:id" component={MemberDetailPage} /><Route path="/attendance" component={AttendancePage} /><Route path="/payments" component={PaymentsPage} /><Route path="/trainers" component={TrainersPage} /><Route path="/expenses" component={ExpensesPage} /><Route path="/reports" component={ReportsPage} /><Route path="/settings" component={SettingsPage} /><Route component={NotFound} /></Switch></AppShell></Show><Show when="signed-out"><Redirect to="/sign-in" /></Show></>}</ErrorBoundary>;
}

function AuthenticatedApp() {
  const [, setLocation] = useLocation();
  return <ClerkProvider
    publishableKey={clerkPubKey}
    proxyUrl={clerkProxyUrl}
    appearance={{
      theme: shadcn,
      cssLayerName: 'clerk',
      variables: { colorPrimary: 'hsl(65 72% 48%)', fontFamily: 'Manrope, sans-serif' },
    }}
    signInUrl={`${basePath}/sign-in`}
    signUpUrl={`${basePath}/sign-up`}
    routerPush={(to) => setLocation(to.startsWith(basePath) ? to.slice(basePath.length) || '/' : to)}
    routerReplace={(to) => setLocation(to.startsWith(basePath) ? to.slice(basePath.length) || '/' : to)}
  >
    <QueryClientProvider client={queryClient}>
      <TooltipProvider>
        <Switch>
          <Route path="/sign-in/*?" component={() => <AuthPage mode="sign-in" />} />
          <Route path="/sign-up/*?" component={() => <AuthPage mode="sign-up" />} />
          <Route component={WorkspaceRouter} />
        </Switch>
        <Toaster />
      </TooltipProvider>
    </QueryClientProvider>
  </ClerkProvider>;
}

function App() { return <WouterRouter base={basePath}><AuthenticatedApp /></WouterRouter>; }
export default App;